import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E8%AE%AF%E9%A3%9E-%E5%88%9B%E5%BB%BA%E5%BA%94%E7%94%A8.Bwg_8mPN.png",r="/newx-doc/assets/%E8%AE%AF%E9%A3%9E%E6%98%9F%E7%81%AB-%E5%AE%98%E6%96%B9.Cadn6TBq.png",E=JSON.parse('{"title":"【模型接入】讯飞星火","description":"","frontmatter":{},"headers":[],"relativePath":"ai/xinghuo.md","filePath":"ai/xinghuo.md","lastUpdated":null}'),h={name:"ai/xinghuo.md"};function p(o,a,l,d,c,k){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="【模型接入】讯飞星火" tabindex="-1">【模型接入】讯飞星火 <a class="header-anchor" href="#【模型接入】讯飞星火" aria-label="Permalink to &quot;【模型接入】讯飞星火&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/xinghu</code>，实现 <a href="https://xinghuo.xfyun.cn/sparkapi" target="_blank" rel="noreferrer">讯飞星火大模型</a> 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>Spark X2、Spark X2 Flash</td><td>XingHuoChatModel</td></tr><tr><td>AI 绘画</td><td>暂未接入</td><td>暂未支持</td></tr></tbody></table><p>补充说明：</p><p>讯飞星火支持 <a href="https://www.xfyun.cn/doc/spark/ImageGeneration.html" target="_blank" rel="noreferrer">图片生成</a> ，未来我们也会进行集成。</p><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>由于讯飞星火是非开源的模型，所以无法私有化部署，需要去官网申请 API Key，然后通过 Spring AI 提供的客户端接入。</p><h3 id="_1-1-申请讯飞密钥" tabindex="-1">1.1 申请讯飞密钥 <a class="header-anchor" href="#_1-1-申请讯飞密钥" aria-label="Permalink to &quot;1.1 申请讯飞密钥&quot;">​</a></h3><p>① 在 <a href="https://xinghuo.xfyun.cn/sparkapi" target="_blank" rel="noreferrer">讯飞星火</a> 上，注册一个账号。</p><p>② 在 <a href="https://xinghuo.xfyun.cn/sparkapi" target="_blank" rel="noreferrer">讯飞星火</a> 上，点击【免费试用】按钮，创建一个应用。</p><p>③ 在 <a href="https://console.xfyun.cn/" target="_blank" rel="noreferrer">控制台</a> 里，开通 Spark X2 或 Spark X2 Flash，并获取 HTTP 协议的 API Key。</p><p><img src="'+n+'" alt="创建应用"></p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，模型对应的接口地址由系统自动选择。如下图所示：</p><p><img src="'+r+`" alt="官方的密钥配置"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>不同版本的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th><th>接口地址</th></tr></thead><tbody><tr><td><code>x2</code></td><td>131072</td><td><a href="https://spark-api-open.xf-yun.com/x2/chat/completions" target="_blank" rel="noreferrer">接口地址</a></td></tr><tr><td><code>x2-flash</code></td><td>262144</td><td><a href="https://spark-api-open.xf-yun.com/agent/v1/chat/completions" target="_blank" rel="noreferrer">接口地址</a></td></tr></tbody></table><h3 id="_2-2-ai-绘画" tabindex="-1">2.2 AI 绘画 <a class="header-anchor" href="#_2-2-ai-绘画" aria-label="Permalink to &quot;2.2 AI 绘画&quot;">​</a></h3><p>TODO 等待 ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 XingHuoChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.xinghuo</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    xinghuo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${XINGHUO_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x2-flash</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code>，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，XingHuoChatModelTests 里有对应的测试用例，可以参考。</p>`,31)])])}const _=t(h,[["render",p]]);export{E as __pageData,_ as default};
